code.cpp:
class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        vector<int> trustCount(n + 1, 0);
        vector<int> trustedByCount(n + 1, 0);

        for (const auto& t : trust) {
            trustCount[t[0]]++;
            trustedByCount[t[1]]++;
        }

        for (int i = 1; i <= n; i++) {
            if (trustCount[i] == 0 && trustedByCount[i] == n - 1) {
                return i;
            }
        }

        return -1;
    }
};
